export const Escena:React.FC=()=>{const {s}=useS();let tree:React.ReactNode=<Shot i={0}/>;for(let i=1;i<A.length;i++)tree=<Paso t={T(A[i])} tipo={(['entrar','forma','barrido','entrar','forma','alejar','barrido','forma','entrar','alejar','forma','barrido'] as const)[i-1]} antes={tree} despues={<Shot i={i}/>} dur={.6}/>;return <AbsoluteFill style={{background:tono(s,[0,en('agua'),en('Dale')],['#954f64','#2e7f7a','#954f64'])}}>{tree}</AbsoluteFill>};
const VOICE_CUES=[{t:.1,s:'whoosh_01'},{t:en('hipo'),s:'pop_01'},{t:en('cúpula'),s:'whoosh_02'},{t:en('diafragma'),s:'click_01'},{t:en('baja'),s:'whoosh_03'},{t:en('aire'),s:'whoosh_04'},{t:en('irrita'),s:'pop_02'},{t:en('golpe'),s:'pop_03'},{t:en('tirón'),s:'whoosh_05'},{t:en('cierran'),s:'click_02'},{t:en('portazo'),s:'pop_01'},{t:en('hic'),s:'pop_02'},{t:en('comer'),s:'papel_01'},{t:en('gas'),s:'pop_03'},{t:en('susto'),s:'pop_01'},{t:en('minutos'),s:'tick_01'},{t:en('bebés'),s:'whoosh_06'},{t:en('nacer'),s:'chime_01'},{t:en('ancestros'),s:'whoosh_02'},{t:en('agua'),s:'whoosh_01'},{t:en('millones'),s:'ding_01'},{t:en('ríe'),s:'pop_02'}];

// Cada desplazamiento corto del seguimiento tiene un whoosh propio. Las
// palabras de datos conservan prioridad y una separación mínima de 0,27 s.
const CAM_STEPS=Array.from({length:Math.ceil(DUR*2.6/2)},(_,j)=>({t:T(j*2)+.12,s:['whoosh_01','whoosh_02','whoosh_03','whoosh_04','whoosh_05','whoosh_06'][j%6]})).filter((e,j,a)=>e.t<DUR-.2&&VOICE_CUES.every(v=>Math.abs(v.t-e.t)>.28)&&(j===0||e.t-a[j-1].t>.3));
function cameraNudge(s:number){return CAM_STEPS.reduce((v,e,j)=>{const z=s-e.t;return v+(z>=0&&z<.7?Math.sin(z/.7*Math.PI)*(j%2?7:-7):0)},0)}
export const SFX=[...VOICE_CUES,...CAM_STEPS].sort((a,b)=>a.t-b.t).filter((v,i,a)=>i===0||v.t-a[i-1].t>=.27);
